import{_ as a,a as l}from"./chunks/image-20261116063402530.DK6B0Klg.js";import{_ as e,o as t,c as r,a2 as o}from"./chunks/framework.CmPiTyN0.js";const f=JSON.parse('{"title":"界面与操作","description":"","frontmatter":{"title":"界面与操作","outline":"deep"},"headers":[],"relativePath":"wiki/interface.md","filePath":"wiki/interface.md","lastUpdated":null}'),n={name:"wiki/interface.md"};function _(s,i,p,c,d,h){return t(),r("div",null,[...i[0]||(i[0]=[o('<p><a href="./../index.html">← 返回 Wiki 首页</a></p><h2 id="_10-界面与操作" tabindex="-1">10. 界面与操作 <a class="header-anchor" href="#_10-界面与操作" aria-label="Permalink to &quot;10. 界面与操作&quot;">​</a></h2><h3 id="_10-1-人在回路" tabindex="-1">10.1 人在回路 <a class="header-anchor" href="#_10-1-人在回路" aria-label="Permalink to &quot;10.1 人在回路&quot;">​</a></h3><ul><li>RVP特色武器之一</li><li>分为电视制导（HITL_TV）和指令线电视制导（HITL_CLOS_TV）两种界面。</li></ul><p><strong>人在回路电视制导（HITL_TV）</strong></p><ul><li>发射后进入弹载电视/热成像回传画面。</li><li>发射手在画面中用准星选择目标点，按锚定键（默认 R）锚定或重新锚定，导弹跟踪该目标点。</li><li>HUD 显示速度、高度、距离、飞行时间、锁定状态和操作提示。</li><li>支持彩色/黑白/热成像切换、滚轮缩放、空爆引爆和退出。</li></ul><p><img src="'+a+'" alt="image-20261116063514262"></p><p><strong>图10.1 人在回路导弹</strong></p><p><strong>人在回路指令线电视制导（HITL_CLOS_TV）</strong></p><ul><li>发射后进入同样的电视/热成像回传画面。</li><li>发射手直接控制导弹舵面转向，屏幕中心显示操纵游标；没有目标锚定流程。</li><li>HUD 显示速度、高度、距离、飞行时间、转向速率和操作提示。</li><li>同样支持画面模式切换、滚轮缩放、空爆引爆和退出。</li></ul><p><img src="'+l+'" alt="image-20261116063402530"></p><p><strong>图10.2 人在回路导弹2</strong></p><h3 id="_10-2-头瞄" tabindex="-1">10.2 头瞄 <a class="header-anchor" href="#_10-2-头瞄" aria-label="Permalink to &quot;10.2 头瞄&quot;">​</a></h3><ul><li>红外制导导弹支持头瞄捕获与离轴发射。</li><li>雷达武器站支持雷达头瞄方便快速锁定指向位置。</li></ul><h3 id="_10-3-告警与提示" tabindex="-1">10.3 告警与提示 <a class="header-anchor" href="#_10-3-告警与提示" aria-label="Permalink to &quot;10.3 告警与提示&quot;">​</a></h3><ul><li>激光照射告警。</li><li>锁定告警与导弹逼近提示。</li><li>辅助设备、DIRCM、ECM、APS、干扰物状态显示。</li><li>命中指示、生物伤害飘字与模块损伤提示。</li><li>动作卡显示当前可用操作与快捷键。</li></ul><hr>',17)])])}const T=e(n,[["render",_]]);export{f as __pageData,T as default};
